/*
 * Sun Sweep: the house, top down, over today's sun wedge.
 * The shapes are drawn by drawing.js, which matches drawing.py.
 */
// A browser cannot resolve a bare "lit", so Lit ships beside the card
// (lit.js is generated by `npm run build`).
import { LitElement, css, html, nothing } from "./lit.js";

import { cardSvg } from "./drawing.js";
import { season } from "./seasons.js";

const DOCS =
  "https://github.com/minchinweb/ha-sunsweep-card/blob/master/docs/configuration.md";
const SHOW = ["show_sun", "show_times", "show_moon", "show_hours", "show_twilight"];
// The four named days. The value is what goes in `date`. `north` and `south`
// are what the day is called in each hemisphere.
const DAYS = [
  { value: "march-equinox", month: "march", north: "Vernal equinox", south: "Autumnal equinox" },
  { value: "june-solstice", month: "june", north: "Summer solstice", south: "Winter solstice" },
  { value: "september-equinox", month: "september", north: "Autumnal equinox", south: "Vernal equinox" },
  { value: "december-solstice", month: "december", north: "Winter solstice", south: "Summer solstice" },
];
// Other spellings that `date` accepts, shown as the day they stand for.
const ALIASES = {
  north: {
    "vernal-equinox": "march-equinox",
    "spring-equinox": "march-equinox",
    spring: "march-equinox",
    "summer-solstice": "june-solstice",
    summer: "june-solstice",
    "autumnal-equinox": "september-equinox",
    "autumn-equinox": "september-equinox",
    "fall-equinox": "september-equinox",
    autumn: "september-equinox",
    "winter-solstice": "december-solstice",
    winter: "december-solstice",
  },
  south: {
    "vernal-equinox": "september-equinox",
    "spring-equinox": "september-equinox",
    spring: "september-equinox",
    "summer-solstice": "december-solstice",
    summer: "december-solstice",
    "autumnal-equinox": "march-equinox",
    "autumn-equinox": "march-equinox",
    "fall-equinox": "march-equinox",
    autumn: "march-equinox",
    "winter-solstice": "june-solstice",
    winter: "june-solstice",
  },
};
const LABELS = {
  entity: "Entity",
  show_sun: "Sun",
  show_times: "Sunrise and sunset",
  show_moon: "Moon",
  show_hours: "Hour lines",
  show_twilight: "Twilight",
  rotation: "Rotation",
  occasion: "Day",
  date: "Date",
  time: "Time",
  tap_action: "Tap action",
};
const HELP = {
  entity: "The Sun Sweep sensor. Leave this on sensor.sun_sweep unless you renamed it.",
  show_sun: "The yellow disc on the ring, while the sun is up.",
  show_times: "Sunrise and sunset, written along the two edges of the day.",
  show_moon: "The grey disc on the ring, while the moon is up.",
  show_hours: "A line for each hour the sun is up. Noon is the heavy spoke.",
  show_twilight: "Blue-grey from civil dawn to civil dusk, under the daylight.",
  rotation:
    "Degrees clockwise, or negative for anticlockwise. North turns with the house, for a tablet mounted sideways.",
  occasion: "Live follows the clock. An equinox or solstice holds the card on that day.",
  date: "The day to hold. The sensor itself stays on the live clock.",
  time: "Clock time on the chosen day. Empty uses the time it is now.",
  tap_action: "What a tap on the card does. None leaves the picture alone.",
};

class SunSweepCard extends LitElement {
  static properties = {
    hass: {},
    config: {},
    // Set by Home Assistant while the card is being added or edited.
    editMode: { type: Boolean },
    preview: { type: Boolean },
    _fixed: { state: true },
    _loading: { state: true },
  };

  static styles = css`
    :host { display: block; }
    svg {
      width: 100%;
      height: auto;
      display: block;
      font-family: var(--ha-font-family, sans-serif);
    }
    .message, .note {
      padding: 16px;
      text-align: center;
      color: var(--primary-text-color);
    }
    .note {
      padding-top: 0;
      color: var(--secondary-text-color);
      font-size: 0.85em;
    }
    .actionable { cursor: pointer; }
    .actionable:focus-visible {
      outline: 2px solid var(--primary-color, #03a9f4);
      outline-offset: 2px;
    }
  `;

  static getConfigElement() {
    return document.createElement("sun-sweep-card-editor");
  }

  static getStubConfig(hass, entities = [], entitiesFallback = []) {
    const candidates = [...entities, ...entitiesFallback];
    const match = candidates.find(
      (id) => hass?.states?.[id]?.attributes?.outline,
    );
    return { entity: match || "sensor.sun_sweep" };
  }

  getCardSize() {
    return 5;
  }

  getGridOptions() {
    return {
      columns: 6,
      rows: 6,
      min_columns: 4,
      min_rows: 4,
    };
  }

  setConfig(config) {
    if (!config || typeof config !== "object" || Array.isArray(config)) {
      throw new Error("Invalid configuration");
    }
    this.config = { ...config };
  }

  shouldUpdate(changed) {
    if (changed.has("config") || changed.has("_fixed") || changed.has("_loading")) {
      return true;
    }
    if (!changed.has("hass")) return true;
    const previous = changed.get("hass");
    if (!previous) return true;
    const entity = this.config?.entity || "sensor.sun_sweep";
    return (
      previous.states?.[entity] !== this.hass?.states?.[entity] ||
      previous.locale !== this.hass?.locale ||
      previous.themes !== this.hass?.themes ||
      previous.config?.time_zone !== this.hass?.config?.time_zone
    );
  }

  willUpdate(changed) {
    if (changed.has("config") || changed.has("hass")) this._loadFixed();
  }

  async _loadFixed() {
    const date = this.config?.date;
    if (!date || !this.hass?.callWS) {
      this._fixedKey = "";
      if (this._loading) this._loading = false;
      if (this._fixed !== undefined) this._fixed = undefined;
      return;
    }
    const key = `${date}|${this.config.time || ""}`;
    if (key === this._fixedKey) return;
    this._fixedKey = key;
    this._loading = true;
    try {
      const attrs = await this.hass.callWS({
        type: "sun_sweep/snapshot",
        date,
        time: this.config.time || undefined,
      });
      if (this._fixedKey !== key) return;
      this._fixed = attrs;
      this._loading = false;
    } catch (err) {
      if (this._fixedKey !== key) return;
      this._fixed = { error: err?.message || "That date could not be drawn." };
      this._loading = false;
    }
  }

  _held() {
    const date = String(this.config?.date || "").trim();
    const key = date.toLowerCase().replaceAll(" ", "-");
    const named = {
      "march-equinox": "the March equinox",
      "june-solstice": "the June solstice",
      "september-equinox": "the September equinox",
      "december-solstice": "the December solstice",
      "vernal-equinox": "the vernal equinox",
      "spring-equinox": "the spring equinox",
      "summer-solstice": "the summer solstice",
      "autumnal-equinox": "the autumnal equinox",
      "autumn-equinox": "the autumn equinox",
      "fall-equinox": "the fall equinox",
      "winter-solstice": "the winter solstice",
      spring: "spring",
      summer: "summer",
      autumn: "autumn",
      winter: "winter",
    };
    let label = named[key];
    const language = this.hass?.locale?.language;
    const timeZone = this.hass?.config?.time_zone;
    if (!label && date.includes("T") && !Number.isNaN(new Date(date).getTime())) {
      label = new Date(date).toLocaleString(language, {
        timeZone,
        dateStyle: "medium",
        timeStyle: "short",
      });
    } else if (!label && /^\d{4}-\d{2}-\d{2}$/.test(date)) {
      const [year, month, day] = date.split("-").map(Number);
      label = new Date(Date.UTC(year, month - 1, day)).toLocaleDateString(language, {
        timeZone: "UTC",
        dateStyle: "medium",
      });
    } else if (!label) {
      label = date;
    }
    const clock =
      this.config?.time && !date.includes("T") ? ` at ${this._face(this.config.time)}` : "";
    return `Held on ${label}${clock}.`;
  }

  _face(clock) {
    const [hour, minute] = String(clock).split(":");
    const sample = new Date(Date.UTC(2026, 0, 1, Number(hour), Number(minute) || 0));
    const cycle = this.hass?.locale?.time_format;
    const hour12 = cycle === "12" ? true : cycle === "24" ? false : undefined;
    return sample.toLocaleTimeString(this.hass?.locale?.language, {
      hour: "numeric",
      minute: "2-digit",
      hour12,
      timeZone: "UTC",
    });
  }

  _on(key) {
    return this.config[key] !== false;
  }

  _clock(iso) {
    const cycle = this.hass?.locale?.time_format;
    const hour12 = cycle === "12" ? true : cycle === "24" ? false : undefined;
    const timeZone = this.hass?.config?.time_zone;
    return new Date(iso).toLocaleTimeString(this.hass?.locale?.language, {
      hour: "numeric",
      minute: "2-digit",
      hour12,
      timeZone,
    });
  }

  _picture(attrs) {
    this._pendingSvg = cardSvg(attrs, {
      show_sun: this._on("show_sun"),
      show_times: this._on("show_times"),
      show_moon: this._on("show_moon"),
      show_hours: this._on("show_hours"),
      show_twilight: this._on("show_twilight"),
      rotation: Number(this.config?.rotation) || 0,
      clock: (iso) => this._clock(iso),
      embedded: true,
    });
    return html`<div class="disc" role="img" aria-label=${this._summary(attrs)}></div>`;
  }

  updated() {
    const slot = this.renderRoot?.querySelector(".disc");
    const svg = this._pendingSvg || "";
    if (!slot || slot._drawn === svg) return;
    slot.innerHTML = svg;
    slot._drawn = svg;
  }

  _summary(attrs) {
    if (attrs.phase === "polar_night") return "The sun stays below the horizon today.";
    if (attrs.phase === "polar_day") return "The sun stays above the horizon today.";
    const bits = [];
    if (attrs.phase === "before_sunrise") bits.push("Before sunrise");
    else if (attrs.phase === "after_sunset") bits.push("After sunset");
    else bits.push("Sun above the horizon");
    if (attrs.sunrise) bits.push(`sunrise ${this._clock(attrs.sunrise)}`);
    if (attrs.sunset) bits.push(`sunset ${this._clock(attrs.sunset)}`);
    return bits.join(", ");
  }

  _interactive() {
    const action = this.config?.tap_action?.action;
    return Boolean(action && action !== "none");
  }

  _tap() {
    const chosen = this.config?.tap_action;
    const action = chosen?.action;
    if (!action || action === "none") return;
    const entity = this.config?.entity || "sensor.sun_sweep";
    if (action === "more-info") {
      this.dispatchEvent(
        new CustomEvent("hass-more-info", {
          bubbles: true,
          composed: true,
          detail: { entityId: entity },
        }),
      );
      return;
    }
    if (action === "navigate" && chosen.navigation_path) {
      history.pushState(null, "", chosen.navigation_path);
      this.dispatchEvent(
        new CustomEvent("location-changed", {
          bubbles: true,
          composed: true,
          detail: { replace: false },
        }),
      );
      return;
    }
    if (action === "url" && chosen.url_path) {
      window.open(chosen.url_path);
      return;
    }
    if (action === "toggle") {
      this.hass?.callService("homeassistant", "toggle", { entity_id: entity });
      return;
    }
    if (action === "perform-action" || action === "call-service") {
      const service = chosen.perform_action || chosen.service;
      if (!service || !service.includes(".")) return;
      const [domain, name] = service.split(".");
      const data = { ...(chosen.service_data || {}), ...(chosen.data || {}) };
      this.hass?.callService(domain, name, data, chosen.target);
    }
  }

  _key(event) {
    if (event.key !== "Enter" && event.key !== " ") return;
    event.preventDefault();
    this._tap();
  }

  render() {
    const entity = this.config?.entity || "sensor.sun_sweep";
    const state = this.hass?.states?.[entity];
    const pinned = Boolean(this.config?.date);
    const waiting = pinned && (this._loading || !this._fixed || this._fixed.error);
    const attrs = pinned ? (this._fixed?.error ? undefined : this._fixed) : state?.attributes;
    let body;
    if (pinned && this._fixed?.error && !this._loading) {
      body = html`<div class="message" aria-live="polite">${this._fixed.error}</div>`;
    } else if (pinned && (this._loading || !this._fixed)) {
      body = html`<div class="message" aria-live="polite">Drawing ${this.config.date}…</div>`;
    } else if (!pinned && !state) {
      body = html`<div class="message">Sun Sweep is not set up.</div>`;
    } else if (!pinned && (state.state === "unavailable" || state.state === "unknown")) {
      body = html`<div class="message">Sun Sweep is not ready yet.</div>`;
    } else if (!attrs?.outline?.length) {
      body = html`<div class="message">House Structure has no building outline for this home yet.</div>`;
    } else {
      body = this._picture(attrs);
    }
    const notes = [];
    // The outline notes are setup help, so they show only while the card is
    // being added or edited, not on a live dashboard.
    const setup = this.editMode || this.preview;
    if (setup && !waiting && attrs?.outline_fallback) {
      notes.push("House Structure is not installed, so this is a plain square.");
    }
    if (setup && !waiting && attrs?.outline_missing) {
      notes.push(
        "House Structure has no building outline for this home yet, so this is a plain square.",
      );
    }
    if (!waiting && attrs?.phase === "polar_night") {
      notes.push("The sun stays below the horizon today.");
    }
    if (pinned && !this._loading && this._fixed && !this._fixed.error) {
      notes.push(this._held());
    }
    const note = notes.length
      ? html`<div class="note">${notes.map((line) => html`<div>${line}</div>`)}</div>`
      : "";
    const interactive = this._interactive();
    return html`
      <ha-card
        class=${interactive ? "actionable" : ""}
        tabindex=${interactive ? "0" : nothing}
        @click=${interactive ? this._tap : nothing}
        @keydown=${interactive ? this._key : nothing}
      >
        ${body}${note}
      </ha-card>
    `;
  }
}

class SunSweepCardEditor extends LitElement {
  static properties = { hass: {}, config: {} };

  setConfig(config) {
    this.config = { ...(config || {}) };
  }

  _occasion() {
    const date = String(this.config?.date || "").trim();
    if (!date) return "live";
    const key = date.toLowerCase().replaceAll(" ", "-");
    if (DAYS.some(({ value }) => value === key)) return key;
    const alias = ALIASES[this._south() ? "south" : "north"][key];
    return alias || "date";
  }

  _south() {
    return Number(this.hass?.config?.latitude) < 0;
  }

  // "Vernal equinox (March 20)": named for the home hemisphere, dated this year.
  _dayLabel(day) {
    const language = this.hass?.locale?.language;
    const timeZone = this.hass?.config?.time_zone;
    const name = this._south() ? day.south : day.north;
    try {
      const when = season(new Date().getFullYear(), day.month);
      const date = when.toLocaleDateString(language, { timeZone, month: "long", day: "numeric" });
      return `${name} (${date})`;
    } catch {
      return name;
    }
  }

  _schema() {
    const fields = [
      { name: "entity", selector: { entity: { domain: "sensor" } } },
      ...SHOW.map((name) => ({ name, selector: { boolean: {} } })),
      {
        name: "rotation",
        // The slider's own number field warns outside min and max, so the
        // range covers a full turn each way: negative is anticlockwise.
        selector: {
          number: { min: -360, max: 360, step: 1, mode: "slider", unit_of_measurement: "°" },
        },
      },
      {
        name: "occasion",
        selector: {
          select: {
            mode: "dropdown",
            options: [
              { value: "live", label: "Live clock" },
              { value: "date", label: "A chosen date" },
              ...DAYS.map((day) => ({ value: day.value, label: this._dayLabel(day) })),
            ],
          },
        },
      },
    ];
    if (this._occasion() === "date") {
      const raw = String(this.config?.date || "");
      const calendar = raw === "" || /^\d{4}-\d{2}-\d{2}$/.test(raw);
      fields.push({ name: "date", selector: calendar ? { date: {} } : { text: {} } });
    }
    const chosen = String(this.config?.date || "");
    if (chosen && !chosen.includes("T")) {
      fields.push({ name: "time", selector: { time: {} } });
    }
    fields.push({
      name: "tap_action",
      selector: {
        ui_action: {
          actions: ["more-info", "toggle", "navigate", "url", "perform-action", "none"],
        },
      },
    });
    return fields;
  }

  _data() {
    const occasion = this._occasion();
    return {
      entity: this.config?.entity || "sensor.sun_sweep",
      show_sun: this.config?.show_sun !== false,
      show_times: this.config?.show_times !== false,
      show_moon: this.config?.show_moon !== false,
      show_hours: this.config?.show_hours !== false,
      show_twilight: this.config?.show_twilight !== false,
      rotation: Number(this.config?.rotation) || 0,
      occasion,
      date: occasion === "date" ? this.config.date || "" : "",
      time: this.config?.time || "",
      tap_action: this.config?.tap_action || { action: "none" },
    };
  }

  _changed(event) {
    const incoming = event.detail.value;
    if (!incoming) return;
    const known = new Set([...SHOW, "entity", "rotation", "date", "time", "tap_action"]);
    const next = {};
    for (const [key, value] of Object.entries(this.config || {})) {
      if (!known.has(key)) next[key] = value;
    }
    if (incoming.entity && incoming.entity !== "sensor.sun_sweep") next.entity = incoming.entity;
    for (const key of SHOW) {
      if (incoming[key] === false) next[key] = false;
    }
    const turn = Number(incoming.rotation);
    if (turn) next.rotation = turn;
    const occasion = incoming.occasion || "live";
    if (occasion === "date") {
      if (incoming.date) next.date = incoming.date;
    } else if (occasion !== "live") {
      next.date = occasion;
    }
    if (next.date && incoming.time) {
      const [hour, minute] = String(incoming.time).split(":");
      if (hour !== undefined && minute !== undefined && minute !== "") {
        next.time = `${hour.padStart(2, "0")}:${minute.padStart(2, "0")}`;
      }
    }
    const tap = incoming.tap_action;
    if (tap?.action && tap.action !== "none") next.tap_action = tap;
    this.config = next;
    this.dispatchEvent(new CustomEvent("config-changed", { detail: { config: next } }));
  }

  render() {
    return html`
      <ha-form
        .hass=${this.hass}
        .schema=${this._schema()}
        .data=${this._data()}
        .computeLabel=${(item) => LABELS[item.name]}
        .computeHelper=${(item) => HELP[item.name]}
        @value-changed=${this._changed}
      ></ha-form>
    `;
  }
}

if (!customElements.get("sun-sweep-card")) {
  customElements.define("sun-sweep-card", SunSweepCard);
  customElements.define("sun-sweep-card-editor", SunSweepCardEditor);
}

window.customCards = window.customCards || [];
if (!window.customCards.some((card) => card.type === "sun-sweep-card")) {
  window.customCards.push({
    type: "sun-sweep-card",
    name: "Sun Sweep",
    description: "Today's sun angles around your house, top down.",
    preview: true,
    documentationURL: DOCS,
    getEntitySuggestion: (hass, entityId) => {
      const outline = hass?.states?.[entityId]?.attributes?.outline;
      if (!outline) return null;
      return { config: { type: "custom:sun-sweep-card", entity: entityId } };
    },
  });
}
